INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Datenmigration dasselbe wie Datensicherung?', 2, '[{"text": "Nein", "correct": true, "because": "Migration überträgt, Sicherung speichert"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Datenmigration?', 3, '[{"text": "Daten in neues System übertragen", "correct": true, "because": "Systemwechsel ermöglichen"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Datenmigration?', 5, '[{"text": "Datenextraktion", "correct": true, "because": "Aus altem System holen"}, {"text": "Datenübertragung", "correct": true, "because": "In neues System laden"}, {"text": "Grafikdesign", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenmigration erfordert Planung. b) Sie ist immer automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Automatisierung nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Datenmigration?', 4, '[{"text": "Datenintegrität", "correct": false, "because": "Muss erhalten bleiben"}, {"text": "Kompatibilität", "correct": false, "because": "Zwischen Systemen nötig"}, {"text": "Monitorfarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenmigration immer komplett automatisiert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Schritte oft nötig"}, {"text": "Ja", "correct": false, "because": "Nicht immer vollautomatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei der Datenmigration?', 3, '[{"text": "ETL-Tools", "correct": true, "because": "Extrahieren, Transformieren, Laden"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet"}, {"text": "Grafiksoftware", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Datenmigration?', 5, '[{"text": "Datenverlust", "correct": true, "because": "Risiko bei Übertragung"}, {"text": "Formatkonflikte", "correct": true, "because": "Unterschiedliche Systeme"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Hauptthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenmigration braucht Tests. b) Sie ist immer schnell. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Datenmigration?', 4, '[{"text": "Quellsystem", "correct": false, "because": "Datenherkunft nötig"}, {"text": "Zielsystem", "correct": false, "because": "Datenziel erforderlich"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Datenmigration nur für Datenbanken?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateien, Anwendungen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen umfasst die Datenmigration?', 4, '[{"text": "Planung", "correct": true, "because": "Strategie festlegen"}, {"text": "Validierung", "correct": true, "because": "Daten prüfen"}, {"text": "Netzwerkdesign", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datenmigration keine Planung braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Planung essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne Planung riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datenmigration?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Verlust vermeiden"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Richtigkeit wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenmigration kann Ausfallzeiten verursachen. b) Sie ist immer verlustfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verlust möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Migration wichtig?', 5, '[{"text": "Datenmapping", "correct": true, "because": "Formatangleichung"}, {"text": "Testphase", "correct": true, "because": "Fehler erkennen"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Migration unwichtig?', 3, '[{"text": "Datenvalidierung", "correct": false, "because": "Sichert Korrektheit"}, {"text": "Backup", "correct": false, "because": "Schützt vor Verlust"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Datenmigration ohne Tests durchgeführt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Aber riskant"}, {"text": "Nein", "correct": false, "because": "Tests empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenmigration nur für Firmen ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch privat möglich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Datenintegrität?', 4, '[{"text": "Verlust vermeiden", "correct": true, "because": "Daten unverändert übertragen"}, {"text": "Schnellere Übertragung", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Grafikverbesserung", "correct": false, "because": "Irrelevant"}]');
